node -e "
const ExcelJS = require('exceljs');
(async () => {
  const wb = new ExcelJS.Workbook();
  await wb.xlsx.readFile('/workspace/testbed/data/order_summary.xlsx');
  const ws = wb.worksheets[0];

  let updated = false;
  ws.eachRow((row, rowNum) => {
    if (row.getCell(1).value === 'ORD-6C71B1') {
      console.log('Before:', row.getCell(4).value);
      row.getCell(4).value = 'confirmed';
      console.log('After: ', row.getCell(4).value);
      updated = true;
    }
  });

  if (updated) {
    await wb.xlsx.writeFile('/workspace/testbed/data/order_summary.xlsx');
    console.log('File saved successfully.');
  } else {
    console.log('Order not found!');
  }
})();
"
